@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=bear
@r1.c1 w.request.constraint request=$r1 on=place attribute=drawn.relation value=by words="by the woods" operator=relation phase=result open_value=true
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.facing value=right operator=eq phase=result key_words=facing
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=drawn.pose value=standing operator=eq phase=result
@r1.c4 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the woods" operator=relation phase=selector

@f1 w.request.filler text="drawn so far"
@r1 w.request.request act=make mood=do words="give me a bear standing by the woods facing right" predicate=give
@r1.t w.request.target request=$r1 family=drawn mode=new determiner=indefinite sort=bear
@r1.c1 w.request.constraint request=$r1 on=place attribute=drawn.relation value=by words="by the woods" operator=relation phase=result open_value=true
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.facing value=right operator=eq phase=result key_words=facing
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=drawn.pose value=standing operator=eq phase=result
@r1.c4 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the woods" operator=relation phase=selector

@f1 w.request.filler text=else
@r1 w.request.request act=change mood=do words="turn the girl in the yellow dress to face right" predicate=turn
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=girl description="the girl in the yellow dress"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.facing value=right operator=eq phase=result key_words=face
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.wear value="the yellow dress" operator=eq phase=result
@r2 w.request.request act=make mood=do words="a small dog on the left facing right"
@r2.t w.request.target request=$r2 family=drawn mode=new determiner=indefinite sort=dog
@r2.c1 w.request.constraint request=$r2 on=size attribute=drawn.size value=small operator=degree phase=result
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=drawn.at value=left words="on the left" operator=region phase=result
@r2.c3 w.request.constraint request=$r2 on=attribute attribute=drawn.facing value=right operator=eq phase=result key_words=facing

@f1 w.request.filler text="side of the canvas"
@r1 w.request.request act=change mood=do words="the woman in the green scarf, facing right"
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=woman description="the woman in the green scarf"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.facing value=right operator=eq phase=result key_words=facing
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.wear value="the green scarf" operator=eq phase=result
